// Regulacja predkosci silnika DC - Arduino Nano
// Silnik: tranzystor MOSFET (MTP75N03) sterowany PWM z pinu 5
// Enkoder: pin 2 (przerwanie zewnetrzne INT0)
//
// Komendy przez port szeregowy (9600 baud, dowolne zakonczenie linii):
//   Z<liczba>  - predkosc zadana [obr/min], np. Z60   (alias: S, s, z)
//   P<liczba>  - wzmocnienie Kp, np. P2.5
//   I<liczba>  - wzmocnienie Ki, np. I0.8
//   D<liczba>  - wzmocnienie Kd, np. D0.05
//   U<0-255>   - tryb reczny: wypelnienie PWM zadane wprost (wylacza PID)
//   R          - powrot do trybu regulacji PID
//   ?          - wypisanie nastaw

#define wejscie 2
#define wyjscie 5

//*** Pomiar czasu ***
float fPredkoscZadana = 0;             // [obr/min]
unsigned long czas = 0;                // aktualny czas
unsigned long czasPID = 0;             // ostatnie wykonanie regulatora
unsigned long czasWyswietlania = 0;    // ostatnie wypisanie na Serial
volatile unsigned long pomiar = 0;     // czas ostatniego przerwania

//*** Pomiar predkosci ***
volatile int pomiary[4];               // czasy miedzy kolejnymi zboczami enkodera [ms]
volatile byte numer = 0;

//*** Regulator ***
float Kp, Ki, Kd;                      // nastawy PID
float fCalka = 0;                      // wartosc calki
float eOld = 0;                        // poprzedni blad
bool trybPID = true;                   // true - PID, false - PWM reczny
int iPWMReczne = 0;
int iPWM = 0;                          // aktualne wypelnienie PWM (0-255)
const float dt = 0.02;                 // okres regulatora [s] (20 ms)

void liczCzas() {
  unsigned long t = millis();
  pomiary[numer] = int(t - pomiar);
  pomiar = t;
  numer++;
  if (numer > 3) numer = 0;
}

// Predkosc w obr/min (4 zbocza = 1/14,58 obrotu walu wyjsciowego)
float predkoscMierzona() {
  int kopia[4];
  noInterrupts();
  for (int i = 0; i < 4; i++) kopia[i] = pomiary[i];
  interrupts();
  float suma = 0;
  for (int i = 0; i < 4; i++) suma += kopia[i];
  return ((suma == 0) || (suma > 3000)) ? 0 : 4115.226 / suma;  // 60000/14.58/suma
}

void setup() {
  pinMode(wejscie, INPUT_PULLUP);
  pinMode(wyjscie, OUTPUT);
  digitalWrite(wyjscie, LOW);
  //*** Komunikacja ***
  Serial.begin(9600);
  Serial.setTimeout(10);
  //*** Ustawienia poczatkowe regulatora PID ***
  Kp = 1.0;
  Ki = 0.5;
  Kd = 0.0;
  fPredkoscZadana = 0;
  analogWrite(wyjscie, 0);
  for (int i = 0; i < 4; i++) pomiary[i] = 0;
  numer = 0;
  attachInterrupt(digitalPinToInterrupt(wejscie), liczCzas, CHANGE);
}

void obslugaSerial() {
  if (!Serial.available()) return;
  char cCo = Serial.read();
  switch (cCo) {
    case '?':
      // Format zgodny z oczekiwaniami funkcji pokaz_nastawy() w Pythonie
      Serial.print("p=");
      Serial.print(Kp, 4);
      Serial.print(" i=");
      Serial.print(Ki, 4);
      Serial.print(" d=");
      Serial.println(Kd, 4);
      break;
    case 'S': case 's':
    case 'Z': case 'z':
      fPredkoscZadana = Serial.parseFloat();
      if (fPredkoscZadana < 0) fPredkoscZadana = 0;
      break;
    case 'P': case 'p':
      Kp = Serial.parseFloat();
      break;
    case 'I': case 'i':
      Ki = Serial.parseFloat();
      fCalka = 0;  // reset calki przy zmianie Ki
      break;
    case 'D': case 'd':
      Kd = Serial.parseFloat();
      break;
    case 'U': case 'u':
      iPWMReczne = constrain(Serial.parseInt(), 0, 255);
      trybPID = false;
      break;
    case 'R': case 'r':
      trybPID = true;
      fCalka = 0;
      eOld = 0;
      break;
  }
}

void loop() {
  czas = millis();

  //*** Zerowanie pomiaru gdy silnik sie nie obraca ***
  if (czas - pomiar > 300) {
    noInterrupts();
    pomiary[numer] = 999;
    numer++;
    if (numer > 3) numer = 0;
    pomiar = czas;
    interrupts();
  }

  obslugaSerial();

  //*** Regulator co 20 ms ***
  if (czas - czasPID > 20) {
    if (trybPID) {
      float predkosc = predkoscMierzona();
      float e = fPredkoscZadana - predkosc;

      // calka z ograniczeniem (anti-windup)
      fCalka += e * dt;
      if (Ki > 0) fCalka = constrain(fCalka, -250 / Ki, 250 / Ki);
      else fCalka = 0;

      float fRozniczka = (e - eOld) / dt;
      eOld = e;

      float noweSterowanie = constrain(Kp * e + Ki * fCalka + Kd * fRozniczka, 0, 255);
      iPWM = (fPredkoscZadana == 0) ? 0 : int(noweSterowanie);
      if (fPredkoscZadana == 0) fCalka = 0;
    } else {
      iPWM = iPWMReczne;
    }
    analogWrite(wyjscie, iPWM);
    czasPID = czas;
  }

  //*** Wypisywanie co 100 ms (format dopasowany do funkcji pokaz_predkosc w Pythonie) ***
  if (czas - czasWyswietlania >= 100) {
    Serial.print("v=");
    Serial.print(predkoscMierzona());
    Serial.print(" s=");
    Serial.print(fPredkoscZadana);
    Serial.print(" w=");
    Serial.println(iPWM);
    czasWyswietlania = czas;
  }
}
